      cursor.pc = structurePiece('tank_slab'); boxC('plain', (x0 + x1) / 2, P.topY - e / 2, (z0 + z1) / 2, x1 - x0, e, z1 - z0, color, 0, 0, 0);
      P.pillars.forEach((p, k) => { cursor.pc = structurePiece('tank_column_' + k); boxC('plain', p.u, (P.baseY + P.topY - e) / 2, p.v, p.side, P.topY - e - P.baseY, p.side, color, 0, 0, 0); });
      cursor.pc = null;
